require "test_helper"

# The MCP 2026-07-28 rules this server follows, one test each (generated by
# maquina:mcp). mcp_post builds a valid request; each test breaks one thing.
class McpConformanceTest < ActionDispatch::IntegrationTest
  WHOAMI = {method: "tools/call", params: {name: "whoami", arguments: {}}}.freeze

  setup do
    @user = users(:mcp_member)
    @token = oauth_token_for(@user, scope: "read")
  end

  # Headers mirror the body (Mcp-Method, Mcp-Name, MCP-Protocol-Version)

  test "a missing Mcp-Method header is a header mismatch" do
    mcp_post({method: "tools/list"}, token: @token, headers: {"Mcp-Method" => nil})

    assert_rpc_error(-32020, :bad_request)
  end

  test "an Mcp-Method header that differs from the body is a header mismatch" do
    mcp_post({method: "tools/list"}, token: @token, headers: {"Mcp-Method" => "tools/call"})

    assert_rpc_error(-32020, :bad_request)
  end

  test "a missing Mcp-Name header on tools/call is a header mismatch" do
    mcp_post(WHOAMI, token: @token, headers: {"Mcp-Name" => nil})

    assert_rpc_error(-32020, :bad_request)
  end

  test "an Mcp-Name header that differs from params.name is a header mismatch" do
    mcp_post(WHOAMI, token: @token, headers: {"Mcp-Name" => "other_tool"})

    assert_rpc_error(-32020, :bad_request)
  end

  test "a missing MCP-Protocol-Version header is a header mismatch" do
    mcp_post({method: "tools/list"}, token: @token, headers: {"MCP-Protocol-Version" => nil})

    assert_rpc_error(-32020, :bad_request)
  end

  test "an MCP-Protocol-Version header that differs from _meta is a header mismatch" do
    mcp_post({method: "tools/list"}, token: @token, headers: {"MCP-Protocol-Version" => "2025-11-25"})

    assert_rpc_error(-32020, :bad_request)
  end

  test "an Mcp-Name header in the base64 sentinel form is decoded before comparing" do
    mcp_post(WHOAMI, token: @token, headers: {"Mcp-Name" => "=?base64?#{Base64.strict_encode64("whoami")}?="})

    assert_response :success
    assert_equal false, response.parsed_body.dig("result", "isError")
  end

  # Per-request protocol version in params._meta

  test "an unsupported protocol version lists the supported ones" do
    meta = {McpTestHelper::MCP_PROTOCOL_VERSION_META => "2025-11-25", McpTestHelper::MCP_CLIENT_CAPABILITIES_META => {}}
    mcp_post({method: "tools/list", params: {_meta: meta}}, token: @token)

    assert_rpc_error(-32022, :bad_request)
    assert_equal [Mcp::PROTOCOL_VERSION], response.parsed_body.dig("error", "data", "supported")
    assert_equal "2025-11-25", response.parsed_body.dig("error", "data", "requested")
  end

  test "a request without the protocol version in _meta is invalid params" do
    mcp_post({method: "tools/list", params: {_meta: {}}}, token: @token)

    assert_rpc_error(-32602, :bad_request)
  end

  # Methods

  test "server/discover answers without a token" do
    mcp_post({method: "server/discover"})

    assert_response :success
    result = response.parsed_body["result"]
    assert_equal [Mcp::PROTOCOL_VERSION], result["supportedVersions"]
    assert result["capabilities"].key?("tools")
    assert_equal Mcp::SERVER_VERSION, result.dig("_meta", "io.modelcontextprotocol/serverInfo", "version")
    assert result.dig("_meta", "io.modelcontextprotocol/serverInfo", "name").present?
  end

  test "tools/list and tools/call need a token" do
    [{method: "tools/list"}, WHOAMI].each do |payload|
      mcp_post(payload)

      assert_response :unauthorized
    end
  end

  test "initialize is a 404 that names the supported revision" do
    legacy = {protocolVersion: "2025-11-25", capabilities: {}, clientInfo: {name: "legacy", version: "1"}}
    post mcp_path, params: {jsonrpc: "2.0", id: 1, method: "initialize", params: legacy}.to_json,
      headers: {"Content-Type" => "application/json"}

    assert_response :not_found
    assert_includes response.parsed_body.dig("error", "message"), "2026-07-28"
  end

  test "an unknown method is method not found" do
    mcp_post({method: "resources/list"}, token: @token)

    assert_rpc_error(-32601, :not_found)
  end

  test "GET and DELETE are not allowed" do
    get mcp_path
    assert_response :method_not_allowed

    delete mcp_path
    assert_response :method_not_allowed
  end

  # Results

  test "every result is complete" do
    mcp_post({method: "server/discover"})
    assert_equal "complete", response.parsed_body.dig("result", "resultType")

    mcp_post({method: "tools/list"}, token: @token)
    assert_equal "complete", response.parsed_body.dig("result", "resultType")

    mcp_post(WHOAMI, token: @token)
    assert_equal "complete", response.parsed_body.dig("result", "resultType")
  end

  test "tools/list is private, cached for five minutes and in registry order" do
    mcp_post({method: "tools/list"}, token: @token)
    result = response.parsed_body["result"]
    names = result["tools"].map { |tool| tool["name"] }

    assert_equal 300_000, result["ttlMs"]
    assert_equal "private", result["cacheScope"]
    assert_equal Mcp::ToolDefinitions.for(@user).map { |definition| definition[:name] }, names
    assert_includes names, "whoami"

    mcp_post({method: "tools/list"}, token: @token)
    assert_equal names, response.parsed_body.dig("result", "tools").map { |tool| tool["name"] }
  end

  # Error codes

  test "a body that is not JSON is a parse error" do
    post mcp_path, params: "{not json", headers: {"Content-Type" => "application/json", "Mcp-Method" => "tools/list"}

    assert_rpc_error(-32700, :bad_request)
  end

  test "a batch is an invalid request" do
    post mcp_path, params: [{jsonrpc: "2.0", id: 1, method: "tools/list"}].to_json,
      headers: {"Content-Type" => "application/json"}

    assert_rpc_error(-32600, :bad_request)
  end

  test "an unknown tool is invalid params, never -32002" do
    mcp_post({method: "tools/call", params: {name: "no_such_tool", arguments: {}}}, token: @token)

    assert_rpc_error(-32602, :ok)
  end

  test "the error table holds every code" do
    codes = McpController::ERRORS.values.map { |error| error[:code] }

    assert_empty [-32700, -32600, -32601, -32602, -32603, -32020, -32021, -32022] - codes
    assert_not_includes codes, -32002
  end

  # Authorization challenges

  test "a 401 points at the protected resource metadata" do
    mcp_post({method: "tools/list"}, token: "not-a-token")

    assert_response :unauthorized
    assert_equal %(Bearer resource_metadata="http://www.example.com/.well-known/oauth-protected-resource/mcp", scope="read"),
      response.headers["WWW-Authenticate"]
  end

  test "a token's last use is recorded at most once a minute" do
    access_token = AccessToken.authenticate(@token)

    mcp_post(WHOAMI, token: @token)
    first_use = access_token.reload.last_used_at
    assert first_use

    travel 30.seconds do
      mcp_post(WHOAMI, token: @token)
      assert_equal first_use, access_token.reload.last_used_at
    end

    travel 2.minutes do
      mcp_post(WHOAMI, token: @token)
      assert_operator access_token.reload.last_used_at, :>, first_use
    end
  end

  test "a write tool with a read token is 403 insufficient_scope" do
    admin = users(:mcp_admin)
    name = Mcp::ToolDefinitions.modules.flat_map { |mod| mod::WRITE_TOOLS }
      .find { |tool| Mcp::ToolDefinitions.owner(tool, admin) }
    skip "No write tool yet: this runs once one is added (maquina:mcp_tool NAME --write)" unless name

    mcp_post({method: "tools/call", params: {name: name, arguments: {}}}, token: oauth_token_for(admin, scope: "read"))

    assert_response :forbidden
    challenge = response.headers["WWW-Authenticate"]
    assert_match(/\ABearer error="insufficient_scope"/, challenge)
    assert_includes challenge, %(scope="read write")
    assert_includes challenge, %(resource_metadata="http://www.example.com/.well-known/oauth-protected-resource/mcp")
  end

  private

  def assert_rpc_error(code, status)
    assert_response status
    assert_equal code, response.parsed_body.dig("error", "code"), response.body
  end
end
